public class JacksonAnnotationIntrospector_findObjectIdInfo_TriageGen0Test {

    private JacksonAnnotationIntrospector introspector;
    private Annotated mockAnnotated;

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
        mockAnnotated = mock(Annotated.class);
    }

    /**
     * Test Case 1: Returns null when the annotation is not present.
     * Covers the branch: if (info == null ...)
     */
    @Test
    public void testFindObjectIdInfo_NullAnnotation() {
        // Mock _findAnnotation behavior via the internal mechanism 
        // Since _findAnnotation is protected and used by findObjectIdInfo, 
        // we need to ensure the mockAnnotated returns nothing for JsonIdentityInfo.class
        when(mockAnnotated.getAnnotation(JsonIdentityInfo.class)).thenReturn(null);

        ObjectIdInfo result = introspector.findObjectIdInfo(mockAnnotated);

        assertNull("Result should be null when annotation is missing", result);
    }

    /**
     * Test Case 2: Returns null when the generator is ObjectIdGenerators.None.class.
     * Covers the branch: if (... || info.generator() == ObjectIdGenerators.None.class)
     */
    @Test
    public void testFindObjectIdInfo_NoneGenerator() {
        JsonIdentityInfo noneInfo = mock(JsonIdentityInfo.class);
        when(noneInfo.generator()).thenReturn(ObjectIdGenerators.None.class);

        // We simulate the finding of the annotation. 
        // In a real Jackson environment, _findAnnotation looks at the Annotated object.
        // For unit testing purposes, we mock the Annotated to return our mock annotation.
        when(mockAnnotated.getAnnotation(JsonIdentityInfo.class)).thenReturn(noneInfo);

        ObjectIdInfo result = introspector.findObjectIdInfo(mockAnnotated);

        assertNull("Result should be null when generator is None", result);
    }

    /**
     * Test Case 3: Returns a valid ObjectIdInfo when a valid JsonIdentityInfo is present.
     * Covers the successful path and construction of ObjectIdInfo.
     */
    @Test
    public void testFindObjectIdInfo_ValidAnnotation() {
        String propertyNameStr = "id";
        Class<?> generatorClass = ObjectIdGenerators.Property.class;
        Class<?> scopeClass = Object.class;
        Object resolver = new Object();

        // Creating a real annotation or a mock that satisfies the requirements
        // Since JsonIdentityInfo is an annotation, we use a mock or a proxy.
        // However, JsonIdentityInfo is an @interface, so we mock it.
        JsonIdentityInfo validInfo = mock(JsonIdentityInfo.class);
        when(validInfo.property()).thenReturn(propertyNameStr);
        when(validInfo.generator()).thenReturn(generatorClass);
        when(validInfo.scope()).thenReturn(scopeClass);
        when(validInfo.resolver()).thenReturn(resolver);

        when(mockAnnotated.getAnnotation(JsonIdentityInfo.class)).thenReturn(validInfo);

        ObjectIdInfo result = introspector.findObjectIdInfo(mockAnnotated);

        assertNotNull("Result should not be null for valid annotation", result);
        assertEquals("Property name should match", PropertyName.construct(propertyNameStr), result.getPropertyName());
        assertEquals("Scope should match", scopeClass, result.getScope());
        assertEquals("Generator should match", generatorClass, result.getGenerator());
        assertEquals("Resolver should match", resolver, result.getResolver());
    }
}
